_EMBEDDED_NHATOT_CSV_GZ_B64: str = ""


def load_nhatot_dataset(custom_path: Optional[str | Path] = None) -> pd.DataFrame:
    """
    Tự động tìm và nạp bộ dữ liệu chuẩn nhatot_cleaned.csv (989 bản ghi sau EDA).
    Nếu đang chạy trên phiên Google Colab mới chưa kịp mount Drive, hàm tự động
    giải nén nhatot_cleaned.csv từ bản nhúng chuẩn của Nhóm 4.
    """
    candidate_paths: List[Path] = []
    if custom_path is not None:
        candidate_paths.append(Path(custom_path))
    candidate_paths.extend([
        Path("nhatot_cleaned.csv"),
        Path("data/nhatot_cleaned.csv"),
        Path("EDA_Updated/data/nhatot_cleaned.csv"),
        Path("../EDA_Updated/data/nhatot_cleaned.csv"),
        Path("downloads/nhatot_cleaned.csv"),
        Path("/content/nhatot_cleaned.csv"),
        Path("/content/drive/MyDrive/[GDG-HUST Gen 6] Nhóm 4 - Đề C1/nhatot_cleaned.csv"),
        Path("/content/drive/MyDrive/[GDG-HUST Gen 6] Nhóm 4 - Đề C1/EDA_Updated/data/nhatot_cleaned.csv"),
    ])

    data_file = next((p for p in candidate_paths if p.exists()), None)
    if data_file is None:
        target = Path("nhatot_cleaned.csv")
        target.write_bytes(gzip.decompress(base64.b64decode(_EMBEDDED_NHATOT_CSV_GZ_B64)))
        data_file = target

    df = pd.read_csv(data_file)
    return df


def _parse_deposit_million(val: Any) -> float:
    """Trích xuất số tiền đặt cọc (đơn vị: triệu VNĐ) từ chuỗi văn bản."""
    if pd.isna(val) or not str(val).strip():
        return np.nan
    s = str(val).lower().replace(".", "").replace(",", ".")
    m = re.search(r"(\d+(?:\.\d+)?)", s)
    if not m:
        return np.nan
    num = float(m.group(1))
    return num / 1e6 if num > 1000 else num


def extract_raw_features_df(df_input: pd.DataFrame) -> pd.DataFrame:
    """
    Trích xuất các đặc trưng cơ sở từ bảng dữ liệu gốc mà CHƯA điền khuyết (chưa chạm tới
    thống kê toàn cục như median/mean) để đảm bảo không xảy ra Data Leakage trước khi chia tập.
    """
    df = df_input.copy()
    df["price_million"] = df["price_vnd"].astype(float) / 1e6
    df.loc[df["price_million"] > 50.0, "price_million"] = 2.0

    df["deposit_raw"] = df["deposit"].apply(_parse_deposit_million)
    df.loc[df["deposit_raw"] > 50.0, "deposit_raw"] = np.nan
    df["has_deposit_info"] = df["deposit_raw"].notna().astype(float)

    text_all = (df["title"].fillna("") + " " + df["description"].fillna("")).str.lower()
    df["area_m2_clean"] = df["area_m2"].astype(float).clip(lower=8.0, upper=120.0)
    furn_map = {"Nhà trống": 0.0, "Nội thất đầy đủ": 2.0, "Nội thất cao cấp": 3.0}
    df["furniture_code"] = df["furniture_status"].map(furn_map).fillna(1.0)

    df["is_central"] = df["district"].astype(str).str.contains(
        "Quận 1$|Quận 3|Phú Nhuận|Bình Thạnh|Tân Bình|Quận 10|Quận 7"
    ).astype(float)
    df["is_suburban"] = df["district"].astype(str).str.contains(
        "Huyện|Quận 12|Bình Tân|Hóc Môn|Bình Chánh|Nhà Bè|Củ Chi"
    ).astype(float)
    df["has_may_lanh"] = text_all.str.contains("máy lạnh|điều hòa|full nội thất|đầy đủ nội thất").astype(float)
    df["has_tu_lanh"] = text_all.str.contains("tủ lạnh|full nội thất").astype(float)
    df["has_may_giat"] = text_all.str.contains("máy giặt").astype(float)
    df["has_gac"] = text_all.str.contains("gác|gác lửng|dup|duplex").astype(float)
    df["has_thang_may"] = text_all.str.contains("thang máy|hầm xe").astype(float)
    df["has_ban_cong"] = text_all.str.contains("ban công|cửa sổ|thoáng mát").astype(float)
    df["has_bep"] = text_all.str.contains("kệ bếp|bếp|nấu ăn").astype(float)
    df["is_studio_duplex"] = text_all.str.contains("studio|duplex|căn hộ dịch vụ|chdv").astype(float)
    df["is_sleepbox_ktx"] = text_all.str.contains("ktx|ký túc xá|sleepbox|ở ghép|giường tầng").astype(float)

    # Chuẩn hóa tên quận/huyện theo quy tắc EDA của Võ Thảo Nguyên
    dist_s = df["district"].fillna("Khác").astype(str).str.strip()
    dist_s = dist_s.replace({
        "Quận 9 cũ)": "Thành phố Thủ Đức",
        "Quận Thủ Đức cũ)": "Thành phố Thủ Đức",
        "Quận 2 cũ)": "Thành phố Thủ Đức",
    })
    df["district_clean"] = dist_s
    df["furniture_cat"] = df["furniture_status"].fillna("Không rõ").astype(str).str.strip()
    df["district_x_furniture"] = df["district_clean"] + " | " + df["furniture_cat"]
    return df


class NhaTotLeakFreePreprocessor:
    """
    Bộ tiền xử lý chống rò rỉ dữ liệu (Leak-Free Fold-Aware Preprocessor):
    - Chỉ học tham số điền khuyết (median tiền cọc hoặc hồi quy kỳ vọng có điều kiện Sparsity-Aware)
      và tham số chuẩn hóa Z-score (cho mô hình tuyến tính/MLP) TRÊN TẬP TRAIN CỦA FOLD HIỆN TẠI.
    - Tuyệt đối không dùng thông tin của tập Validation hay tập Test trong bước fit().
    """
    def __init__(self, impute_strategy: str = "median", scale_numeric: bool = False):
        if impute_strategy not in ("median", "sparsity_aware"):
            raise ValueError("impute_strategy phải là 'median' hoặc 'sparsity_aware'")
        self.impute_strategy = impute_strategy
        self.scale_numeric = scale_numeric
        self.deposit_median_: float = 3.2
        self.beta_sparsity_: Optional[np.ndarray] = None
        self.mean_: Optional[np.ndarray] = None
        self.std_: Optional[np.ndarray] = None
        self.is_fitted_: bool = False

    def fit(self, df_train_raw: pd.DataFrame, y_train: Optional[np.ndarray] = None) -> "NhaTotLeakFreePreprocessor":
        dep = df_train_raw["deposit_raw"].to_numpy(dtype=np.float64)
        valid_dep = dep[~np.isnan(dep)]
        self.deposit_median_ = float(np.median(valid_dep)) if len(valid_dep) > 0 else 3.2

        if self.impute_strategy == "sparsity_aware":
            obs = ~np.isnan(dep)
            Z = np.column_stack([
                np.ones(len(df_train_raw)),
                df_train_raw["area_m2_clean"].to_numpy(dtype=np.float64),
                df_train_raw["furniture_code"].to_numpy(dtype=np.float64),
                df_train_raw["is_central"].to_numpy(dtype=np.float64),
                df_train_raw["is_suburban"].to_numpy(dtype=np.float64),
            ])
            if np.sum(obs) >= 10:
                self.beta_sparsity_, _, _, _ = np.linalg.lstsq(Z[obs], dep[obs], rcond=None)
            else:
                self.beta_sparsity_ = np.zeros(Z.shape[1], dtype=np.float64)

        X_tr = self._build_matrix(df_train_raw)
        if self.scale_numeric:
            self.mean_ = X_tr.mean(axis=0)
            std = X_tr.std(axis=0)
            self.std_ = np.where(std > 1e-12, std, 1.0)
        self.is_fitted_ = True
        return self

    def _build_matrix(self, df_part: pd.DataFrame) -> np.ndarray:
        df_c = df_part.copy()
        dep = df_c["deposit_raw"].to_numpy(dtype=np.float64).copy()
        missing = np.isnan(dep)
        if self.impute_strategy == "sparsity_aware" and self.beta_sparsity_ is not None:
            if np.any(missing):
                Z = np.column_stack([
                    np.ones(len(df_c)),
                    df_c["area_m2_clean"].to_numpy(dtype=np.float64),
                    df_c["furniture_code"].to_numpy(dtype=np.float64),
                    df_c["is_central"].to_numpy(dtype=np.float64),
                    df_c["is_suburban"].to_numpy(dtype=np.float64),
                ])
                dep[missing] = np.clip(Z[missing] @ self.beta_sparsity_, 1.0, 15.0)
        else:
            dep[missing] = self.deposit_median_
        df_c["deposit_filled"] = dep
        return df_c[FEATURE_NAMES_15].to_numpy(dtype=np.float64)

    def transform(self, df_part_raw: pd.DataFrame) -> np.ndarray:
        if not self.is_fitted_:
            raise RuntimeError("Phải gọi fit() trên tập Train trước khi gọi transform()!")
        X = self._build_matrix(df_part_raw)
        if self.scale_numeric and self.mean_ is not None and self.std_ is not None:
            X = (X - self.mean_) / self.std_
        return X

    def fit_transform(self, df_train_raw: pd.DataFrame, y_train: Optional[np.ndarray] = None) -> np.ndarray:
        return self.fit(df_train_raw, y_train).transform(df_train_raw)


def get_fixed_train_test_and_kfold_splits(
    df_raw: Optional[pd.DataFrame] = None,
    random_state: int = RANDOM_STATE,
    test_size: float = TEST_SIZE,
    n_splits: int = CV_FOLDS,
    save_json_path: Optional[str | Path] = None,
) -> Dict[str, Any]:
    """
    Khởi tạo bộ chỉ số chia tập Train/Test (80/20 -> 792 Train / 197 Test) và
    5-Fold Cross-Validation cố định cho toàn bộ Nhóm 4.
    """
    if df_raw is None:
        df_raw = load_nhatot_dataset()
    df_proc = extract_raw_features_df(df_raw)
    n_total = len(df_proc)

    rng_split = np.random.default_rng(random_state)
    all_indices = rng_split.permutation(n_total)
    n_test = int(test_size * n_total)
    test_idx = all_indices[:n_test]
    train_idx = all_indices[n_test:]

    # Điền khuyết median chuẩn được tính CHỈ TRÊN TẬP TRAIN
    train_deposit_median = float(df_proc.iloc[train_idx]["deposit_raw"].median())
    df_proc["deposit_filled"] = df_proc["deposit_raw"].fillna(train_deposit_median)

    X_all = df_proc[FEATURE_NAMES_15].to_numpy(dtype=np.float64)
    y_all = df_proc["price_million"].to_numpy(dtype=np.float64)

    X_train, y_train = X_all[train_idx], y_all[train_idx]
    X_test, y_test = X_all[test_idx], y_all[test_idx]

    cat_train_df = df_proc.iloc[train_idx][CAT_COL_NAMES_3].reset_index(drop=True)
    cat_test_df = df_proc.iloc[test_idx][CAT_COL_NAMES_3].reset_index(drop=True)

    # Chia 5 Fold CV cố định trên tập Train (792 mẫu -> 2 fold 159 val, 3 fold 158 val)
    rng_cv = np.random.default_rng(random_state)
    cv_perm = rng_cv.permutation(len(X_train))
    fold_sizes = np.full(n_splits, len(X_train) // n_splits, dtype=int)
    fold_sizes[: len(X_train) % n_splits] += 1
    cv_splits: List[Tuple[np.ndarray, np.ndarray]] = []
    current = 0
    for f_size in fold_sizes:
        val_f = cv_perm[current : current + f_size]
        tr_f = np.concatenate([cv_perm[:current], cv_perm[current + f_size :]])
        cv_splits.append((tr_f, val_f))
        current += f_size

    if save_json_path is not None:
        payload = {
            "project": "GDG-HUST Data & AI Probation Gen 6 - Group 4 - Topic C1",
            "task": "C1-04 Fixed Train/Test & 5-Fold CV Splits",
            "random_state": random_state,
            "test_size": test_size,
            "cv_folds": n_splits,
            "n_total": int(n_total),
            "n_train": int(len(train_idx)),
            "n_test": int(len(test_idx)),
            "train_deposit_median_million": round(train_deposit_median, 4),
            "feature_names_15": FEATURE_NAMES_15,
            "cat_col_names_3": CAT_COL_NAMES_3,
            "leakage_forbidden_cols": list(LEAKAGE_FORBIDDEN_COLS),
            "train_idx": [int(i) for i in train_idx],
            "test_idx": [int(i) for i in test_idx],
            "cv_splits_relative_to_train": [
                {
                    "fold": int(f_idx + 1),
                    "n_fold_train": int(len(tr_f)),
                    "n_fold_val": int(len(va_f)),
                    "fold_train_idx": [int(i) for i in tr_f],
                    "fold_val_idx": [int(i) for i in va_f],
                }
                for f_idx, (tr_f, va_f) in enumerate(cv_splits)
            ],
        }
        Path(save_json_path).write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")

    return {
        "df_proc": df_proc,
        "feature_names": list(FEATURE_NAMES_15),
        "cat_col_names": list(CAT_COL_NAMES_3),
        "train_idx": train_idx,
        "test_idx": test_idx,
        "train_deposit_median": train_deposit_median,
        "X_train": X_train,
        "y_train": y_train,
        "X_test": X_test,
        "y_test": y_test,
        "cat_train_df": cat_train_df,
        "cat_test_df": cat_test_df,
        "CV_SPLITS": cv_splits,
    }


def assert_no_data_leakage(
    feature_names: Sequence[str],
    train_idx: Sequence[int],
    test_idx: Sequence[int],
    cv_splits: Sequence[Tuple[np.ndarray, np.ndarray]],
    X_train: np.ndarray,
    X_test: np.ndarray,
) -> Dict[str, Any]:
    """
    Hàm kiểm định tự động 5 điều kiện chống rò rỉ dữ liệu (Anti-Data-Leakage Guard):
    1. Không chứa bất kỳ cột cấm nào trong LEAKAGE_FORBIDDEN_COLS (như price_per_m2, price_vnd).
    2. Tập Train và tập Test rời nhau tuyệt đối (disjoint).
    3. Trong từng Fold CV, tập Fold-Train và Fold-Validation rời nhau tuyệt đối.
    4. Hợp của 5 tập Fold-Validation phủ kín đúng 100% tập Train (không bỏ sót, không trùng lặp).
    5. Ma trận đặc trưng không chứa NaN hay Inf.
    """
    leaked_cols = [c for c in feature_names if c in LEAKAGE_FORBIDDEN_COLS]
    if leaked_cols:
        raise AssertionError(f"PHÁT HIỆN DATA LEAKAGE! Các cột cấm xuất hiện trong X: {leaked_cols}")

    set_tr, set_te = set(map(int, train_idx)), set(map(int, test_idx))
    if not set_tr.isdisjoint(set_te):
        raise AssertionError("PHÁT HIỆN DATA LEAKAGE! Tập Train và Test có mẫu trùng nhau!")

    all_val_indices: List[int] = []
    for f_idx, (tr_f, va_f) in enumerate(cv_splits):
        s_tr_f, s_va_f = set(map(int, tr_f)), set(map(int, va_f))
        if not s_tr_f.isdisjoint(s_va_f):
            raise AssertionError(f"Fold {f_idx+1} có mẫu trùng giữa Fold-Train và Fold-Val!")
        all_val_indices.extend(map(int, va_f))

    if len(all_val_indices) != len(train_idx) or len(set(all_val_indices)) != len(train_idx):
        raise AssertionError("Hợp của các tập Validation trong 5-Fold CV không phủ kín 1-1 tập Train!")

    if not np.isfinite(X_train).all() or not np.isfinite(X_test).all():
        raise AssertionError("Ma trận X_train hoặc X_test còn chứa NaN / Inf!")

    return {
        "status": "PASSED",
        "n_features": len(feature_names),
        "n_train": len(train_idx),
        "n_test": len(test_idx),
        "n_folds": len(cv_splits),
        "disjoint_train_test": True,
        "disjoint_all_cv_folds": True,
    }


def calc_metrics(y_true: np.ndarray, y_pred: np.ndarray) -> Dict[str, float]:
    """Tính bộ 3 thước đo chuẩn của Nhóm 4: RMSE, MAE (triệu VNĐ/tháng) và R²."""
    y_true = np.asarray(y_true, dtype=np.float64).ravel()
    y_pred = np.asarray(y_pred, dtype=np.float64).ravel()
    diff = y_true - y_pred
    mse = float(np.mean(diff ** 2))
    rmse = math.sqrt(mse)
    mae = float(np.mean(np.abs(diff)))
    ss_res = float(np.sum(diff ** 2))
    ss_tot = float(np.sum((y_true - np.mean(y_true)) ** 2))
    r2 = 1.0 - (ss_res / ss_tot) if ss_tot > 0 else 0.0
    return {"rmse": rmse, "mae": mae, "r2": r2, "mse": mse}


def evaluate_model_cv_and_test(
    model_name: str,
    family: str,
    model_factory: Callable[[], Any],
    X_train: np.ndarray,
    y_train: np.ndarray,
    X_test: np.ndarray,
    y_test: np.ndarray,
    cv_splits: Sequence[Tuple[np.ndarray, np.ndarray]],
    df_train_raw: Optional[pd.DataFrame] = None,
    df_test_raw: Optional[pd.DataFrame] = None,
    impute_strategy: str = "median",
    scale_numeric: bool = False,
) -> Tuple[Dict[str, Any], Any]:
    """
    Hàm chấm điểm chuẩn 5-Fold Cross-Validation + Hold-out Test Set chống Data Leakage:
    - Nếu truyền df_train_raw & df_test_raw, hàm sẽ khởi tạo NhaTotLeakFreePreprocessor riêng
      bên trong từng Fold CV để tính lại median / Z-score chỉ trên 4/5 dữ liệu của Fold đó!
    """
    fold_rmses, fold_maes, fold_r2s = [], [], []

    for tr_f, va_f in cv_splits:
        if df_train_raw is not None:
            prep = NhaTotLeakFreePreprocessor(impute_strategy=impute_strategy, scale_numeric=scale_numeric)
            X_tr_f = prep.fit_transform(df_train_raw.iloc[tr_f], y_train[tr_f])
            X_va_f = prep.transform(df_train_raw.iloc[va_f])
        else:
            X_tr_f, X_va_f = X_train[tr_f], X_train[va_f]

        m_cv = model_factory()
        m_cv.fit(X_tr_f, y_train[tr_f])
        preds_va = m_cv.predict(X_va_f)
        res = calc_metrics(y_train[va_f], preds_va)
        fold_rmses.append(res["rmse"])
        fold_maes.append(res["mae"])
        fold_r2s.append(res["r2"])

    t0 = time.perf_counter()
    if df_train_raw is not None and df_test_raw is not None:
        prep_full = NhaTotLeakFreePreprocessor(impute_strategy=impute_strategy, scale_numeric=scale_numeric)
        X_tr_full = prep_full.fit_transform(df_train_raw, y_train)
        X_te_full = prep_full.transform(df_test_raw)
    else:
        X_tr_full, X_te_full = X_train, X_test

    m_full = model_factory()
    m_full.fit(X_tr_full, y_train)
    fit_time = time.perf_counter() - t0

    tr_metrics = calc_metrics(y_train, m_full.predict(X_tr_full))
    te_metrics = calc_metrics(y_test, m_full.predict(X_te_full))

    row = {
        "Mô hình": model_name,
        "Nhóm": family,
        "CV RMSE (Mean)": float(np.mean(fold_rmses)),
        "CV RMSE (Std)": float(np.std(fold_rmses, ddof=1)),
        "CV MAE": float(np.mean(fold_maes)),
        "CV R²": float(np.mean(fold_r2s)),
        "Train RMSE": tr_metrics["rmse"],
        "Test RMSE": te_metrics["rmse"],
        "Test MAE": te_metrics["mae"],
        "Test R²": te_metrics["r2"],
        "Fit Time (s)": fit_time,
    }
    return row, m_full
